-- Comentarios da Lei 15.040/2024, lote 5 (arts. 81 a 100). Autorizados pela Jessica em 22/10/2026; so a partir do texto no banco.
-- Reverter: update legislacao set contexto=null, aplicacao_pratica=null where codigo='lei15040' and numero between 81 and 100 and paragrafo is null and inciso is null;
update legislacao l set contexto=v.c, aplicacao_pratica=v.a from (values
(81,'Critérios de apuração da dívida da seguradora','Em caso de dúvida sobre critérios e fórmulas destinados à apuração do valor da dívida da seguradora, serão adotados aqueles que forem mais favoráveis ao segurado ou ao beneficiário, vedado o enriquecimento sem causa.'),
(82,'Relatório de regulação e liquidação','O relatório de regulação e liquidação do sinistro é documento comum às partes.'),
(83,'Entrega de documentos em caso de negativa de cobertura','Negada a cobertura, no todo ou em parte, a seguradora deverá entregar ao interessado os documentos produzidos ou obtidos durante a regulação e a liquidação do sinistro que fundamentem sua decisão. O parágrafo único dispõe que a seguradora não está obrigada a entregar documentos e demais elementos probatórios que sejam considerados confidenciais ou sigilosos por lei ou que possam causar danos a terceiros, salvo em razão de decisão judicial ou arbitral.'),
(84,'Despesas com regulação e liquidação','Correm por conta da seguradora todas as despesas com a regulação e a liquidação do sinistro, salvo as realizadas para a apresentação dos documentos predeterminados para comunicação da ocorrência e para prova da identificação e legitimidade do interessado, além de outros documentos ordinariamente em poder do interessado.'),
(85,'Procedimentos de regulação e liquidação sem reconhecimento de dívida','A execução dos procedimentos de regulação e liquidação de sinistro não importa em reconhecimento de nenhuma obrigação de pagamento do valor do seguro por parte da seguradora.'),
(86,'Prazo para manifestação sobre a cobertura','A seguradora terá o prazo máximo de 30 (trinta) dias para manifestar-se sobre a cobertura, sob pena de decair do direito de recusá-la, contado da data de apresentação da reclamação ou do aviso de sinistro pelo interessado, acompanhados de todos os elementos necessários à decisão a respeito da existência de cobertura. O § 1º dispõe que os elementos necessários à decisão sobre a cobertura devem ser expressamente arrolados nos documentos probatórios do seguro. O § 2º dispõe que a seguradora ou o regulador do sinistro poderão solicitar documentos complementares, de forma justificada, ao interessado, desde que lhe seja possível produzi-los. O § 3º dispõe que, solicitados documentos complementares dentro do prazo do caput, o prazo para a manifestação sobre a cobertura suspende-se por no máximo 2 (duas) vezes, recomeçando a correr no primeiro dia útil subsequente àquele em que for atendida a solicitação. O § 4º dispõe que o prazo do caput somente pode ser suspenso 1 (uma) vez nos sinistros relacionados a seguros de veículos automotores e em todos os demais seguros em que a importância segurada não exceda o correspondente a 500 (quinhentas) vezes o salário mínimo vigente. O § 5º dispõe que a autoridade fiscalizadora poderá fixar prazo superior ao do caput para tipos de seguro em que a verificação da existência de cobertura implique maior complexidade na apuração, respeitado o limite máximo de 120 (cento e vinte) dias. O § 6º dispõe que a recusa de cobertura deve ser expressa e motivada, não podendo a seguradora inovar posteriormente o fundamento, salvo quando, depois da recusa, vier a tomar conhecimento de fatos que anteriormente desconhecia.'),
(87,'Prazo para pagamento da indenização ou do capital','Reconhecida a cobertura, a seguradora terá o prazo máximo de 30 (trinta) dias para pagar a indenização ou o capital estipulado. O § 1º dispõe que os elementos necessários à quantificação dos valores devidos devem ser expressamente arrolados nos documentos probatórios do seguro. O § 2º dispõe que a seguradora ou o liquidante do sinistro poderão solicitar documentos complementares, de forma justificada, ao interessado, desde que lhe seja possível produzi-los. O § 3º dispõe que, solicitados documentos complementares dentro do prazo do caput, o prazo para o pagamento suspende-se por no máximo 2 (duas) vezes, recomeçando a correr no primeiro dia útil subsequente àquele em que for atendida a solicitação. O § 4º dispõe que o prazo do caput somente pode ser suspenso 1 (uma) vez nos sinistros relacionados a seguros de veículos automotores e seguros de vida e integridade física, assim como em todos os demais seguros em que a importância segurada não exceda o correspondente a 500 (quinhentas) vezes o salário mínimo vigente. O § 5º dispõe que a autoridade fiscalizadora poderá fixar prazo superior ao do caput para tipos de seguro em que a liquidação dos valores devidos implique maior complexidade na apuração, respeitado o limite máximo de 120 (cento e vinte) dias. O § 6º dispõe que o valor devido apurado deve ser apresentado de forma fundamentada ao interessado, não podendo a seguradora inovar posteriormente, salvo quando vier a tomar conhecimento de fatos que anteriormente desconhecia.'),
(88,'Mora da seguradora','A mora da seguradora fará incidir multa de 2% (dois por cento) sobre o montante devido, corrigido monetariamente, sem prejuízo dos juros legais e da responsabilidade por perdas e danos desde a data em que a indenização ou o capital segurado deveriam ter sido pagos, conforme disposto nos arts. 86 e 87.'),
(89,'Limite da garantia e da indenização ao valor do interesse','Os valores da garantia e da indenização não poderão superar o valor do interesse, ressalvadas as exceções previstas na Lei.'),
(90,'Limite da indenização ao valor da garantia','A indenização não poderá exceder o valor da garantia, ainda que o valor do interesse lhe seja superior.'),
(91,'Rateio no sinistro parcial','Na hipótese de sinistro parcial, o valor da indenização devida não será objeto de rateio em razão de seguro contratado por valor inferior ao do interesse, salvo disposição em contrário. O § 1º dispõe que, quando expressamente pactuado o rateio, a seguradora exemplificará na apólice a fórmula para cálculo da indenização. O § 2º dispõe que a aplicação do rateio em razão de infrasseguro superveniente será limitada aos casos em que for expressamente afastado na apólice o regime de ajustamento final de prêmio, e o aumento do valor do interesse lesado decorrer de ato voluntário do segurado.'),
(92,'Seguro a valor de novo','É lícito contratar o seguro a valor de novo. O § 1º dispõe que é lícito convencionar a reposição ou a reconstrução paulatina com pagamentos correspondentes, salvo quando esse regime impedir a reposição ou a reconstrução. O § 2º dispõe que, nos seguros de que trata o artigo, não são admitidas cláusulas de rateio.'),
(93,'Vício não aparente e não declarado','Não se presume na garantia do seguro a obrigação de indenizar o vício não aparente e não declarado no momento da contratação do seguro, nem seus efeitos exclusivos. O § 1º dispõe que, salvo disposição em contrário, se houver cobertura para o vício, a garantia compreende tanto os danos ao bem no qual se manifestou o vício quanto aqueles decorrentes do vício. O § 2º dispõe que a simples inspeção prévia pela seguradora de riscos relacionados com atividades empresariais não autoriza a presunção de conhecimento do vício.'),
(94,'Sub-rogação da seguradora nos seguros de dano','A seguradora sub-roga-se nos direitos do segurado pelas indenizações pagas nos seguros de dano. O § 1º dispõe que é ineficaz qualquer ato do segurado que diminua ou extinga a sub-rogação. O § 2º dispõe que o segurado é obrigado a colaborar no exercício dos direitos derivados da sub-rogação, respondendo pelos prejuízos que causar à seguradora. O § 3º dispõe que a sub-rogação da seguradora não poderá implicar prejuízo ao direito remanescente do segurado ou do beneficiário contra terceiros.'),
(95,'Exclusão da ação de sub-rogação','A seguradora não terá ação própria ou derivada de sub-rogação quando o sinistro decorrer de culpa não grave de cônjuge ou parentes até o segundo grau, consanguíneos ou por afinidade, do segurado ou do beneficiário (inciso I) ou de empregados ou pessoas sob a responsabilidade do segurado (inciso II). O parágrafo único dispõe que, quando o culpado pelo sinistro for garantido por seguro de responsabilidade civil, é admitido o exercício do direito excluído pelo caput contra a seguradora que o garantir.'),
(96,'Rateio dos bens atingidos pelo sinistro','A seguradora e o segurado ratearão os bens atingidos pelo sinistro, na proporção do prejuízo suportado.'),
(97,'Seguros de pessoa com finalidade indenizatória','Os seguros contra os riscos de morte e de perda de integridade física de pessoa que visem a garantir direito patrimonial de terceiro ou que tenham finalidade indenizatória submetem-se, no que couber, às regras do seguro de dano. O parágrafo único dispõe que, quando, no momento do sinistro, o valor da garantia superar o valor do direito patrimonial garantido, o excedente sujeitar-se-á às regras do seguro de vida, e será credor da diferença aquele sobre cuja vida ou integridade física foi contratado o seguro e, no caso de morte, o beneficiário, observando-se as disposições do Capítulo III da Lei.'),
(98,'Seguro de responsabilidade civil','O seguro de responsabilidade civil garante o interesse do segurado contra os efeitos da imputação de responsabilidade e do seu reconhecimento, assim como o dos terceiros prejudicados à indenização. O § 1º dispõe que, no seguro de responsabilidade civil, o risco pode caracterizar-se pela ocorrência do fato gerador, da manifestação danosa ou da imputação de responsabilidade. O § 2º dispõe que, na garantia de gastos com a defesa contra a imputação de responsabilidade, deverá ser estabelecido um limite específico e diverso daquele destinado à indenização dos prejudicados.'),
(99,'Acessórios legais da indenização no seguro de responsabilidade civil','A indenização, no seguro de responsabilidade civil, está sujeita aos mesmos acessórios legais incidentes sobre a dívida do responsável.'),
(100,'Dever de colaboração do responsável garantido','O responsável garantido pelo seguro que não colaborar com a seguradora ou praticar atos em detrimento dela responderá pelos prejuízos a que der causa, cabendo-lhe informar prontamente a seguradora das comunicações recebidas que possam gerar reclamação futura (inciso I); fornecer os documentos e outros elementos a que tiver acesso e que lhe forem solicitados pela seguradora (inciso II); comparecer aos atos processuais para os quais for intimado (inciso III); e abster-se de agir em detrimento dos direitos e das pretensões da seguradora (inciso IV).')
) as v(n,c,a)
where l.codigo='lei15040' and l.numero=v.n and l.paragrafo is null and l.inciso is null and l.vigente;
